import { create_orders } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_global_customers } from "@/mixins/GetGlobalCustomers.js";
import { get_sub_categories } from "@/mixins/GetMasterSubcategories.js";
import SnackBar from "@/components/SnackBar.vue";
import CountryList from "@/JsonFiles/CountryList.json";
export default {
  components: {
    SnackBar,
    CountryList
  },
  props: {
    addOrderDialog: Boolean
  },
  mixins: [get_global_customers, get_sub_categories],
  data() {
    return {
      customerName: "",
      customerEmail: "",
      contactNumber: "",
      advanceReceived: "",
      customersArray: [],
      masterSub: [],
      subCategory: "",
      date: new Date().toISOString().substr(0, 10),
      minDate: new Date().toISOString().substr(0, 10),
      datePicker: false,
      tempDate: new Date().toISOString().substr(0, 10),
      loading: false,
      isNewCustomer: "EXISTINGCUST",
      rules: {
        required: v => !!v || "Required"
      },
      selectedProduct: null,
      selectedProducts: [],
      SnackBarComponent: {},
      balanceAmount: "",
      countryCodes: [],
      userCCcode: "",
      search: "",
      manualCustomer: "",
      totalAmount: "",
      customerAddress: ""
    };
  },
  async created() {
    this.isNewCustomer = "EXISTINGCUST";
    this.countries();
    this.customersArray = [];
    await this.get_global_customers();
    this.fetch_customers();
    await this.get_sub_categories();
    this.masterSub = this.MasterSubCategories;
  },
  computed: {
    computedDateDisplay() {
      return this.displayFormatDate(this.date);
    }
  },
  methods: {
    displayFormatDate(date) {
      if (!date) return "";
      if (typeof date === "string" && date.includes("-")) {
        const [year, month, day] = date.split("-");
        return `${day}/${month}/${year}`;
      }
      if (date instanceof Date) {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        return `${day}/${month}/${year}`;
      }
      return date;
    },
    saveDate() {
      this.date = this.tempDate;
      this.datePicker = false;
    },
    calculateBalance() {
      const total = parseFloat(this.totalAmount) || 0;
      const advance = parseFloat(this.advanceReceived) || 0;
      if (advance > total) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Advance amount cannot exceed total amount.",
          timeout: 5000,
          Top: true
        };
        this.advanceReceived = total;
        this.balanceAmount = 0;
      } else {
        this.balanceAmount = total - advance;
      }
    },
    validateAdvanceAmount(value) {
      const total = parseFloat(this.totalAmount) || 0;
      const advance = parseFloat(value) || 0;
      return advance <= total || "Advance cannot be greater than Total Amount";
    },
    countries() {
      var countryWithCc = [];
      this.countriesData = [];
      CountryList.forEach(element => {
        countryWithCc.push({
          label: element.name + "(" + element.dial_code + ")",
          value: element.dial_code
        });
        this.countriesData.push(element.name);
      });
      var countryListt = countryWithCc;
      this.countryCodes = countryListt;
    },
    addProduct() {
      if (!this.selectedProduct) return;
      const exists = this.selectedProducts.find(p => p.sub_category_id === this.selectedProduct.sub_category_id);
      if (!exists) {
        this.selectedProducts.push({
          ...this.selectedProduct,
          quantity: 1
        });
        this.selectedProduct = null;
      } else {
        this.$emit("errorMsg", "Product already added.");
      }
    },
    increaseQuantity(index) {
      this.selectedProducts[index].quantity++;
    },
    decreaseQuantity(index) {
      if (this.selectedProducts[index].quantity > 1) {
        this.selectedProducts[index].quantity--;
      }
    },
    removeProduct(index) {
      this.selectedProducts.splice(index, 1);
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.selectedProducts = [];
      this.$refs.form.reset();
    },
    validateAndSave() {
      const isFormValid = this.$refs.form.validate();
      if (!isFormValid) return;
      if (this.selectedProducts.length === 0) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please add at least one product.",
          timeout: 5000,
          Top: true
        };
        return;
      }
      this.place_order();
    },
    is_number(evt, value) {
      evt = evt || window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      }
      if (value.length >= 14 && charCode >= 48 && charCode <= 57) {
        evt.preventDefault();
      }
    },
    fetch_customers() {
      this.customersArray = this.masterCustomers;
    },
    productData() {
      const productInfoArray = this.selectedProducts.map(product => ({
        product_name: product.sub_category_name,
        product_id: product.sub_category_id,
        quantity: product.quantity
      }));
      return JSON.stringify(productInfoArray);
    },
    async place_order() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_orders, {
          input: {
            customer_name: this.isNewCustomer === "NEWCUSTOMER" ? this.manualCustomer : this.customerName.customer_name,
            customer_country_code: this.isNewCustomer === "NEWCUSTOMER" ? this.userCCcode : this.customerName.customer_country_code,
            customer_contact_number: this.isNewCustomer === "NEWCUSTOMER" ? this.contactNumber : this.customerName.customer_contact_number,
            customer_email_id: this.isNewCustomer === "NEWCUSTOMER" ? this.customerEmail : this.customerName.customer_email_id,
            customer_address: this.isNewCustomer === "NEWCUSTOMER" ? this.customerAddress : this.customerName.customer_address,
            advance_recevied: this.advanceReceived,
            expected_delevery_date: this.date,
            remaining_amount: this.balanceAmount,
            total_amount: this.totalAmount,
            product: this.productData()
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_orders);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.selectedProducts = [];
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
